import asyncio, json, websockets

async def call():
    headers = {"Authorization": f"Bearer {TOKEN}"}
    async with websockets.connect('wss://{HOST}/', additional_headers=headers) as ws:
        await ws.send("{
  "jsonrpc": "2.0",
  "id": 1,
  "src": "my-client",
  "dst": "FLEET_MANAGER",
  "method": "assignment.Create",
  "params": {
    "subjectType": "user",
    "subjectId": "string",
    "personaId": "00000000-0000-4000-8000-000000000000",
    "scope": {}
  }
}")
        print(json.loads(await ws.recv()))

asyncio.run(call())

