  "src": "my-client",
  "dst": "FLEET_MANAGER",
  "method": "eth.SetConfig",
  "params": {
    "shellyID": "string",
    "config": {}
  }
}")
        print(json.loads(await ws.recv()))

asyncio.run(call())

