import asyncio, json, websockets

async def call():
    headers = {"Authorization": f"Bearer {TOKEN}"}
    async with websockets.connect('wss://{HOST}/', additional_headers=headers) as ws:
        await ws.send("{
  "jsonrpc": "2.0",
  "id": 1,
  "src": "my-client",
  "dst": "FLEET_MANAGER",
  "method": "trv.SetConfig",
  "params": {
    "shellyID": "string",
    "id": 0,
    "config": {}
  }
}")
        print(json.loads(await ws.recv()))

asyncio.run(call())

